// FIND SINGLE DUE DILIGENCE TASK WITH FULL CONTEXT
const tasks = $input.first().json.result || [];
console.log(`🔍 Scanning ${tasks.length} Kanboard tasks`);

// Find first valid Due Diligence task
let validTask = null;
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Must match: "Due Diligence: [Company Name]" with website URL in description
  if (title.toLowerCase().includes('due diligence:') && description.includes('http')) {
    const companyName = title.replace(/due diligence:\s*/i, '').trim();
    const websiteMatch = description.match(/https?:\/\/[^\s]+/);
    const websiteUrl = websiteMatch ? websiteMatch[0] : null;

    if (companyName && websiteUrl) {
      validTask = {
        kanboard_id: task.id,
        title: title,
        description: description,
        company_name: companyName,
        website_url: websiteUrl,
        project_id: task.project_id || 1,
        // Initialize retry counters
        maker_retry_count: 0,
        max_retries: 3
      };
      break; // Take first valid task only
    }
  }
}

if (!validTask) {
  console.log('ℹ️ No valid Due Diligence tasks found');
  throw new Error('No Due Diligence tasks found');
}

console.log(`🎯 Selected Task: ${validTask.company_name}`);

return {
  json: {
    ...validTask,
    workflow_action: 'VALIDATE_PREREQUISITES'
  }
};

// VALIDATE PREREQUISITES (SIMPLIFIED)
const taskData = $('Find DD Task').first().json;

console.log(`📋 Validating prerequisites for: ${taskData.company_name}`);

const missingItems = [];

// Check title format
if (!taskData.title.toLowerCase().includes('due diligence:')) {
  missingItems.push('Title must start with "Due Diligence: [Company Name]"');
}

// Check website URL in description
if (!taskData.website_url) {
  missingItems.push('Description must contain the official website URL');
}

// Skip attachment validation - proceed with any task that has proper title and URL

if (missingItems.length > 0) {
  console.log(`❌ Missing prerequisites: ${missingItems.length} items`);
  missingItems.forEach(item => console.log(`   • ${item}`));

  return {
    json: {
      ...taskData,
      prerequisites_valid: false,
      missing_items: missingItems,
      workflow_action: 'POST_MISSING_COMMENT'
    }
  };
}

console.log('✅ All prerequisites valid - proceeding with Knowledge Base');

return {
  json: {
    ...taskData,
    prerequisites_valid: true,
    workflow_action: 'BUILD_KNOWLEDGE_BASE'
  }
};

// BUILD COMPREHENSIVE KNOWLEDGE BASE WITH ALL USER DATA
const taskData = $('Validate Prerequisites').first().json;

// Get all comments (user input)
let userComments = [];
try {
  const commentsResponse = $('Get Task Comments').first();
  if (commentsResponse && commentsResponse.json && commentsResponse.json.result) {
    userComments = commentsResponse.json.result.filter(comment => 
      comment.username !== 'admin' || // Not from our workflow
      !comment.comment.includes('SECTION COMPLETED') // Not our completion comments
    );
    console.log(`📋 Found ${userComments.length} user comments`);
  }
} catch (error) {
  console.log(`⚠️ Comments fetch failed: ${error.message}`);
}

// Get task attachments
let attachments = [];
try {
  const attachResponse = $('Get Task Attachments').first();
  if (attachResponse && attachResponse.json && attachResponse.json.result) {
    attachments = attachResponse.json.result;
    console.log(`📎 Found ${attachments.length} attachments`);
  }
} catch (error) {
  console.log(`⚠️ Attachments fetch failed: ${error.message}`);
}

// Get website content
let websiteContent = '';
try {
  const websiteResponse = $('Fetch Website').first();
  if (websiteResponse && websiteResponse.json) {
    websiteContent = websiteResponse.json.toString();
  } else if (websiteResponse && websiteResponse.data) {
    websiteContent = websiteResponse.data.toString();
  }
} catch (error) {
  console.log(`⚠️ Website fetch failed: ${error.message}`);
}

// Get FinBERT analysis
let finbertData = null;
try {
  const finbertResponse = $('Run FinBERT Analysis').first();
  if (finbertResponse && finbertResponse.json) {
    finbertData = finbertResponse.json;
    console.log('✅ FinBERT analysis completed');
  }
} catch (error) {
  console.log(`⚠️ FinBERT analysis failed: ${error.message}`);
}

console.log(`📚 Building Comprehensive Knowledge Base for: ${taskData.company_name}`);
console.log(`🌐 Website content: ${websiteContent ? 'Available' : 'Failed to fetch'}`);
console.log(`💬 User comments: ${userComments.length} items`);
console.log(`📎 Attachments: ${attachments.length} items`);
console.log(`🔍 FinBERT data: ${finbertData ? 'Available' : 'Not available'}`);

// Create comprehensive knowledge base chunks
let kbChunks = [];

// Website chunks
if (websiteContent) {
  let websiteHost = taskData.website_url;
  try {
    const match = taskData.website_url.match(/https?:\/\/([^\/]+)/);
    websiteHost = match ? match[1] : taskData.website_url;
  } catch (error) {
    websiteHost = taskData.website_url.replace(/[^a-zA-Z0-9]/g, '_');
  }

  const websiteChunks = chunkText(websiteContent, 800);
  websiteChunks.forEach((chunk, index) => {
    kbChunks.push({
      chunk_id: `kb://${taskData.kanboard_id}/website:${websiteHost}/p1#c${index + 1}`,
      content: chunk,
      source_type: 'website',
      source_id: websiteHost,
      page: 1,
      chunk_index: index + 1
    });
  });
}

// User comments chunks (CRITICAL for business context)
userComments.forEach((comment, index) => {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/user_input:${comment.username}/c${index + 1}`,
    content: `User Input from ${comment.username}: ${comment.comment}`,
    source_type: 'user_input',
    source_id: comment.username,
    page: 1,
    chunk_index: index + 1
  });
});

// Task description and title as KB chunks
kbChunks.push({
  chunk_id: `kb://${taskData.kanboard_id}/task_info:description/c1`,
  content: `Task Description: ${taskData.description}`,
  source_type: 'task_info',
  source_id: 'description',
  page: 1,
  chunk_index: 1
});

kbChunks.push({
  chunk_id: `kb://${taskData.kanboard_id}/task_info:title/c1`,
  content: `Company Name and Task Title: ${taskData.title}`,
  source_type: 'task_info',
  source_id: 'title',
  page: 1,
  chunk_index: 1
});

// Attachments info (even if we can't download content)
attachments.forEach((file, index) => {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/attachment:${file.name}/c1`,
    content: `Attachment Available: ${file.name} (${file.size} bytes) - Uploaded by user as supporting material`,
    source_type: 'attachment',
    source_id: file.name,
    page: 1,
    chunk_index: 1
  });
});

// FinBERT analysis chunk
if (finbertData) {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/finance:finbert/p1#c1`,
    content: `Financial Analysis Results: ${JSON.stringify(finbertData)}`,
    source_type: 'finance',
    source_id: 'finbert',
    page: 1,
    chunk_index: 1
  });
}

console.log(`📊 Comprehensive Knowledge Base created: ${kbChunks.length} chunks`);

// Helper function to chunk text
function chunkText(text, maxTokens) {
  const words = text.split(/\s+/);
  const chunks = [];
  let currentChunk = [];

  for (const word of words) {
    currentChunk.push(word);
    if (currentChunk.length >= maxTokens * 0.75) {
      chunks.push(currentChunk.join(' '));
      currentChunk = [];
    }
  }

  if (currentChunk.length > 0) {
    chunks.push(currentChunk.join(' '));
  }

  return chunks;
}

return {
  json: {
    ...taskData,
    kb_chunks: kbChunks,
    website_content_available: !!websiteContent,
    finbert_available: !!finbertData,
    user_comments_count: userComments.length,
    attachments_count: attachments.length,
    total_chunks: kbChunks.length,
    workflow_action: 'START_MCA_LOOP'
  }
};

// GENERATE MAKER PROMPT WITH RETRY CONTEXT
const taskData = $input.first().json;
const kbChunks = taskData.kb_chunks || [];
const retryCount = taskData.maker_retry_count || 0;

const sectionName = "Business Model & Unit Economics";

// Format KB chunks for prompt - prioritize user input
const userInputChunks = kbChunks.filter(chunk => chunk.source_type === 'user_input' || chunk.source_type === 'task_info');
const websiteChunks = kbChunks.filter(chunk => chunk.source_type === 'website');
const otherChunks = kbChunks.filter(chunk => !['user_input', 'task_info', 'website'].includes(chunk.source_type));

// Prioritize user input in prompt
const prioritizedChunks = [...userInputChunks, ...websiteChunks.slice(0, 3), ...otherChunks];

const kbChunksText = prioritizedChunks.map(chunk => 
  `[${chunk.chunk_id}]: ${chunk.content.substring(0, 600)}...`
).join('\n\n');

// Add retry-specific instructions
let retryInstructions = '';
if (retryCount > 0) {
  retryInstructions = `\n\nIMPORTANT - RETRY #${retryCount}:\nPrevious attempt was rejected. Focus on providing more specific details and stronger evidence from the KB chunks. If information is truly missing, clearly state "Insufficient evidence in KB" rather than making assumptions.`;
}

const makerPrompt = `SYSTEM:
You are the MAKER agent for Due Diligence analysis. Write the Business Model & Unit Economics section.
Use ONLY the provided KB chunks. Do not invent or assume any data.
PRIORITIZE user-provided information from comments and task details.
Cite every claim with [KB:chunk_id] references.
${retryInstructions}

USER:
Company: ${taskData.company_name}
Website: ${taskData.website_url}
Section: ${sectionName}

Knowledge Base (${kbChunks.length} chunks available):
${kbChunksText}

Write a comprehensive "${sectionName}" section covering:
1. **Value Proposition**: How the company creates and delivers value
2. **Revenue Streams**: Primary ways the company generates revenue
3. **Pricing Strategy**: How services/products are priced
4. **Key Cost Drivers**: Major operational costs and expenses
5. **Unit Economics**: CAC, LTV, gross margins, payback periods (only if available in KB)

Requirements:
- Use professional Markdown formatting
- Cite EVERY factual claim with [KB:chunk_id]
- If specific metrics are unavailable, state "Insufficient evidence in KB for [specific metric]"
- Focus on evidence-based analysis only
- Include tables/bullets for clarity where appropriate`;

console.log(`📝 Generated Maker prompt for section: ${sectionName} (Retry: ${retryCount})`);
console.log(`📚 Using ${kbChunks.length} KB chunks (${userInputChunks.length} user inputs)`);

return {
  json: {
    ...taskData,
    section_name: sectionName,
    maker_prompt: makerPrompt,
    workflow_action: 'RUN_MAKER'
  }
};

// ENHANCED CHECKER WITH RETRY AWARENESS
const taskData = $('Generate Smart Maker Prompt').first().json;
const makerResponse = $input.first().json.response;
const retryCount = taskData.maker_retry_count || 0;

console.log(`📝 Maker completed section: ${taskData.section_name} (Retry: ${retryCount})`);
console.log(`📊 Maker output length: ${makerResponse.length} characters`);

// Get relevant KB chunks that were cited or should be checked
const kbChunks = taskData.kb_chunks || [];
const citedChunks = kbChunks.filter(chunk => 
  makerResponse.includes(chunk.chunk_id)
);

const kbChunksForChecker = citedChunks.length > 0 ? citedChunks : kbChunks.slice(0, 8); // Use cited or first 8

// Enhanced checker prompt with retry context
let retryContext = '';
if (retryCount > 0) {
  retryContext = `\n\nRETRY CONTEXT: This is attempt #${retryCount + 1}. Previous versions were rejected. Be more lenient if the Maker has made genuine improvements and clearly indicates missing information with "Insufficient evidence in KB".`;
}

const checkerPrompt = `SYSTEM:
You are the CHECKER. Validate the Maker's analysis against available KB evidence.
Approve if the work shows reasonable effort and properly indicates missing data.
Reject only for clear hallucinations or completely unsupported claims.
${retryContext}

USER:
Maker Analysis:
${makerResponse}

Available KB Evidence:
${kbChunksForChecker.map(chunk => `[${chunk.chunk_id}]: ${chunk.content}`).join('\n\n')}

Validation Criteria:
1) Claims supported by KB evidence OR clearly marked as "Insufficient evidence"
2) No invented numbers or fictional data
3) Proper [KB:chunk_id] citations for factual claims
4) Professional quality and completeness
5) Honest about data limitations

Respond ONLY in JSON:
{
  "approved": true|false,
  "quality_score": <1-10>,
  "issues": ["specific problems if any"],
  "instructions_for_maker": "specific guidance for improvement"
}`;

return {
  json: {
    ...taskData,
    maker_output: makerResponse,
    checker_prompt: checkerPrompt,
    cited_chunks: citedChunks.length,
    workflow_action: 'RUN_CHECKER'
  }
};

// SMART RETRY LOGIC - NO SPAM COMMENTS
const taskData = $('Enhanced Checker Logic').first().json;
const checkerResponse = $input.first().json.response;
const retryCount = taskData.maker_retry_count || 0;
const maxRetries = taskData.max_retries || 3;

let checkerDecision;
try {
  checkerDecision = JSON.parse(checkerResponse);
} catch (error) {
  console.log('❌ Failed to parse Checker JSON response');
  checkerDecision = {
    approved: false,
    quality_score: 1,
    issues: ['Invalid JSON response from Checker'],
    instructions_for_maker: 'Checker returned invalid JSON. Please retry section.'
  };
}

console.log(`🔍 Checker Decision: ${checkerDecision.approved ? 'APPROVED' : 'REJECTED'}`);
console.log(`📊 Quality Score: ${checkerDecision.quality_score}/10`);
console.log(`🔄 Retry Count: ${retryCount}/${maxRetries}`);

if (!checkerDecision.approved) {
  // Check if we've exceeded retry limit
  if (retryCount >= maxRetries) {
    console.log(`⚠️ Max retries exceeded. Posting final rejection.`);
    return {
      json: {
        ...taskData,
        checker_approved: false,
        checker_decision: checkerDecision,
        workflow_action: 'POST_FINAL_REJECTION'
      }
    };
  }

  // Silent retry - no comment, just increment counter and retry
  console.log(`🔄 Silently retrying... (${retryCount + 1}/${maxRetries})`);
  (checkerDecision.issues || []).forEach((issue, index) => {
    console.log(`   ${index + 1}. ${issue}`);
  });

  return {
    json: {
      ...taskData,
      maker_retry_count: retryCount + 1,
      checker_decision: checkerDecision,
      workflow_action: 'SILENT_RETRY'
    }
  };
}

// Checker approved - proceed to Approver
const approverPrompt = `SYSTEM:
You are the APPROVER. Final business review of the Maker's analysis.
Focus on strategic value and executive-level insights.

USER:
Maker Analysis:
${taskData.maker_output}

Checker Assessment:
${JSON.stringify(checkerDecision)}

Approval Criteria:
- Strategic relevance for business decisions
- Clear, actionable insights for executives
- Professional presentation quality
- Honest about limitations when data is missing

Respond ONLY in JSON:
{
  "approved": true|false,
  "final_feedback": "brief rationale",
  "send_back_instructions": "guidance if rejected"
}`;

return {
  json: {
    ...taskData,
    checker_approved: true,
    checker_decision: checkerDecision,
    approver_prompt: approverPrompt,
    workflow_action: 'RUN_APPROVER'
  }
};

