// APPROVER DECISION WITH RETRY LOGIC
const taskData = $('Smart Retry Decision').first().json;
const approverResponse = $input.first().json.response;

let approverDecision;
try {
  approverDecision = JSON.parse(approverResponse);
} catch (error) {
  console.log('❌ Failed to parse Approver JSON response');
  approverDecision = {
    approved: false,
    final_feedback: 'Invalid JSON response from Approver',
    send_back_instructions: 'Approver returned invalid JSON. Please retry section.'
  };
}

console.log(`✅ Approver Decision: ${approverDecision.approved ? 'APPROVED' : 'REJECTED'}`);
console.log(`💼 Feedback: ${approverDecision.final_feedback}`);

if (!approverDecision.approved) {
  // Approver rejection also triggers retry (if under limit)
  const retryCount = taskData.maker_retry_count || 0;
  const maxRetries = taskData.max_retries || 3;

  if (retryCount >= maxRetries) {
    console.log(`⚠️ Approver rejection after max retries`);
    return {
      json: {
        ...taskData,
        approver_approved: false,
        approver_decision: approverDecision,
        workflow_action: 'POST_FINAL_REJECTION'
      }
    };
  }

  console.log(`🔄 Approver triggered retry: ${retryCount + 1}/${maxRetries}`);

  return {
    json: {
      ...taskData,
      maker_retry_count: retryCount + 1,
      approver_decision: approverDecision,
      workflow_action: 'SILENT_RETRY'
    }
  };
}

// Both Checker and Approver approved - SUCCESS!
console.log('🎉 Section fully approved by MCA workflow!');

return {
  json: {
    ...taskData,
    approver_approved: true,
    approver_decision: approverDecision,
    checker_decision: taskData.checker_decision,
    final_markdown: taskData.maker_output,
    workflow_action: 'GENERATE_FINAL_OUTPUT'
  }
};

// GENERATE SUCCESS COMMENT WITH COMPLETE ANALYSIS
const taskData = $input.first().json;

console.log(`📄 Preparing success comment for: ${taskData.company_name}`);
console.log(`📝 Section: ${taskData.section_name}`);
console.log(`🔄 Completed after ${taskData.maker_retry_count || 0} retries`);

// Create complete success comment with analysis
let finalComment = `🎉 **DUE DILIGENCE ANALYSIS COMPLETED**\n\n`;
finalComment += `📄 **Company:** ${taskData.company_name}\n`;
finalComment += `📝 **Section:** ${taskData.section_name}\n`;
finalComment += `**Generated:** ${(new Date()).toISOString()}\n`;
finalComment += `**Quality Score:** ${taskData.checker_decision.quality_score}/10\n`;
finalComment += `**Attempts:** ${(taskData.maker_retry_count || 0) + 1}\n`;
finalComment += `**Website:** ${taskData.website_url}\n\n`;
finalComment += `---\n\n`;

// Add the complete approved analysis
finalComment += taskData.final_markdown;

// Add comprehensive metadata footer
finalComment += `\n\n---\n\n`;
finalComment += `## Quality Assurance & Data Sources\n\n`;
finalComment += `**Checker Validation:** ✅ Approved (Score: ${taskData.checker_decision.quality_score}/10)\n`;
finalComment += `**Approver Review:** ✅ Approved\n`;
finalComment += `**Knowledge Base Sources:** ${taskData.total_chunks} chunks\n`;
finalComment += `**User Input Comments:** ${taskData.user_comments_count || 0} items\n`;
finalComment += `**Task Attachments:** ${taskData.attachments_count || 0} files\n`;
finalComment += `**FinBERT Analysis:** ${taskData.finbert_available ? '✅ Available' : '❌ Not Available'}\n`;
finalComment += `**Website Data:** ${taskData.website_content_available ? '✅ Available' : '❌ Not Available'}\n`;
finalComment += `\n⏰ **Analysis Completed:** ${(new Date()).toISOString()}`;

return {
  json: {
    ...taskData,
    final_comment: finalComment,
    workflow_action: 'POST_SUCCESS_COMMENT'
  }
};
